import{_ as a,C as n,o,c as s,j as t,a as i,E as h,a6 as d}from"./chunks/framework.CCKCzdWs.js";const c="/screenshots/vscode-uncovered.png",b=JSON.parse('{"title":"Coverage in the editor","description":"The lines your tests ran, marked in VS Code and the JetBrains IDEs, Rider included: the lines run and not run, the tests behind each function and line, the lines changed since the coverage run, and the changes no test reaches.","frontmatter":{"title":"Coverage in the editor","description":"The lines your tests ran, marked in VS Code and the JetBrains IDEs, Rider included: the lines run and not run, the tests behind each function and line, the lines changed since the coverage run, and the changes no test reaches.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/editor-coverage.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/editor-coverage.html"}],["meta",{"property":"og:title","content":"Coverage in the editor | Piwi Dashboard"}],["meta",{"property":"og:description","content":"The lines your tests ran, marked in VS Code and the JetBrains IDEs, Rider included: the lines run and not run, the tests behind each function and line, the lines changed since the coverage run, and the changes no test reaches."}]]},"headers":[],"relativePath":"features/editor-coverage.md","filePath":"features/editor-coverage.md","lastUpdated":1793161814000}'),l={name:"features/editor-coverage.md"};function u(g,e,f,m,v,p){const r=n("Needs");return o(),s("div",null,[e[0]||(e[0]=t("h1",{id:"coverage-in-the-editor",tabindex:"-1"},[i("Coverage in the editor "),t("a",{class:"header-anchor",href:"#coverage-in-the-editor","aria-label":'Permalink to "Coverage in the editor"'},"​")],-1)),h(r,{reporter:"",fixtures:"",backend:""}),e[1]||(e[1]=d('<p>With <a href="/guide/concepts.html#coverage">coverage</a> recorded, the <a href="./editors.html">editor extensions</a> mark the lines of an application file your tests ran, the executable lines no test runs, and the lines you changed since, in VS Code and in the JetBrains IDEs, Rider included. A lens above each function names the tests that ran it and runs them; the hover on a line lists them.</p><h2 id="turn-it-on" tabindex="-1">Turn it on <a class="header-anchor" href="#turn-it-on" aria-label="Permalink to &quot;Turn it on&quot;">​</a></h2><p>The marks show what the reporter records, per test:</p><ul><li><strong>Server code</strong>: an ASP.NET Core backend built for coverage, with the reporter&#39;s <code>coverage.server</code> set to <code>lines</code>, or <code>PIWI_COVERAGE_SERVER=lines</code>: <a href="./server-coverage.html">Server coverage</a> has the steps. With <code>functions</code>, every line of a function that ran is marked run, and no line is marked as not run.</li><li><strong>Browser code</strong>: recorded per file (<a href="./code-reach.html#turn-it-on">code reach</a>), so such a file lists its tests in its top lens, with no line marks; with <code>coverage.browser: &#39;functions&#39;</code>, every line of a function that ran is marked run, with its lens above it. No line of a browser file is marked as not run.</li></ul><p>Nothing else is needed in the editor. A test file, a file no recorded coverage names lines of, and a project without coverage show nothing of it: no mark, no lens line, no command, no hover text.</p><p>The editor asks the instance for a file&#39;s coverage when you open it, and, when the project&#39;s code reach can tell, only for a file it says coverage recorded. It asks again on a refresh and when a run ends, naming the answer it holds, which the instance confirms unchanged without sending it again. Typing asks nothing: the marks are placed on your edits locally.</p><h2 id="the-marks" tabindex="-1">The marks <a class="header-anchor" href="#the-marks" aria-label="Permalink to &quot;The marks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mark</th><th>Meaning</th></tr></thead><tbody><tr><td>Solid, teal</td><td>A test ran the line. The hover names the tests.</td></tr><tr><td>Solid, slate</td><td>The line is executable and no test runs it. Shown when the run recorded the file&#39;s executable lines, which <code>lines</code> does.</td></tr><tr><td>Dashed, amber</td><td>The line changed since the coverage run: what runs it is not known until a run records it again.</td></tr><tr><td>Solid, orange</td><td>In a file no test reaches, the line changed since the default branch: an <a href="#uncovered-changes">uncovered change</a>.</td></tr></tbody></table><p>Teal and slate are the colors the dashboard marks a file&#39;s source in. The hover on a marked line ends by saying what the marks mean.</p><p>In VS Code the marks are a bar at the left edge of each line, in <code>piwi.coverageRunBorder</code>, <code>piwi.coverageNotRunBorder</code>, <code>piwi.coverageChangedBorder</code> and <code>piwi.uncoveredChangeBorder</code>, which a theme or <code>workbench.colorCustomizations</code> can restyle; all but the lines run also show in the overview ruler. In a JetBrains IDE they are at the left of the gutter and in the scroll bar, and hovering either shows what the lines are and what the marks mean. Restyle them under <strong>Settings → Editor → Color Scheme → Piwi → Coverage</strong>, where the error stripe color is the mark&#39;s, and a background, none by default, tints the lines too.</p><h2 id="changed-since-the-coverage-run" tabindex="-1">Changed since the coverage run <a class="header-anchor" href="#changed-since-the-coverage-run" aria-label="Permalink to &quot;Changed since the coverage run&quot;">​</a></h2><p>Coverage names the lines of one version of a file, by its git blob id, the id <code>git hash-object</code> gives the file as the test ran it. Your file may be another version: edited since, or the coverage may come from a CI run on an older commit. The marks come from, in order:</p><ol><li><strong>The version that is your file as it stands</strong>, saved or not, whatever its line endings and byte order mark: its marks are exact.</li><li><strong>The version your file was saved as</strong>, when you edited it since.</li><li><strong>The version the most tests recorded that your repository holds</strong> (<code>git cat-file</code>).</li></ol><p>From the second and the third, the lines are placed on your file through the diff between the two, as <a href="./editor-failures.html#failures-follow-your-edits">failures follow your edits</a>: a line moved by the edits above it keeps its mark on its new line; a line the diff adds or rewrites is marked changed since the coverage run, not guessed; a line it removes loses its mark. Blank lines are never marked changed.</p><p>When your repository holds none of the versions, such as a commit you have not fetched, no line is marked and the file&#39;s lens says <code>coverage recorded on another version</code>. Fetching it brings the marks back on the next refresh.</p><h2 id="uncovered-changes" tabindex="-1">Uncovered changes <a class="header-anchor" href="#uncovered-changes" aria-label="Permalink to &quot;Uncovered changes&quot;">​</a></h2><p>A file the editor can observe and no test reaches has its changes marked before the pull request&#39;s <a href="./uncovered-changes.html">uncovered changes</a> list them, by the same rule: a page (Nuxt <code>pages/**</code>) while Piwi knows the pages your tests visit, or a server route (<code>server/api/**</code>, <code>server/routes/**</code>) while code reach maps routes to tests, that no test visits, requests or runs. Its lines changed since the default branch are marked orange: those added since the commit your branch left it at (the merge base with <code>origin/main</code>, else <code>main</code>), uncommitted changes included, blank lines left out. The file&#39;s top lens says <code>Uncovered changes: 12 lines changed since main, and no test reaches this file</code>, and so does the hover on a marked line. A test that reaches the file, or the change reaching the default branch, takes the marks away. A file nothing can observe, and a project whose code reach is missing or cut short, show nothing.</p><figure><img src="'+c+'" alt="VS Code: a server route no test reaches, its lines changed since main marked orange, the top lens and the hover saying why"><figcaption>A server route no test requests: the lines changed since <code>main</code> are marked, and the hover says why.</figcaption></figure><h2 id="lenses-and-hover" tabindex="-1">Lenses and hover <a class="header-anchor" href="#lenses-and-hover" aria-label="Permalink to &quot;Lenses and hover&quot;">​</a></h2><ul><li><strong>Top of the file</strong>: <code>Reached by 6 tests · 1 failing · 41 of 63 lines run · 3 lines changed since the coverage run</code>. The tests are those code reach and the coverage name; the line counts show when the run recorded the executable lines. A click runs those tests.</li><li><strong>Above each function a test ran</strong>: <code>Reached by 2 tests · 1 failing</code>, the tests that ran it. A click runs them, as <a href="./editor-runs.html#run-tests">Runs from the editor</a> describes.</li><li><strong>Hover</strong>: on a line tests ran, each test with its latest result and a link to its page in the dashboard; on a line no test runs, <code>no test runs this line</code>; on a changed line, that it changed since the coverage run.</li></ul><h2 id="refresh-the-marks-with-a-local-run" tabindex="-1">Refresh the marks with a local run <a class="header-anchor" href="#refresh-the-marks-with-a-local-run" aria-label="Permalink to &quot;Refresh the marks with a local run&quot;">​</a></h2><p>A run started from a lens of a server file records the backend&#39;s coverage by line: the editor adds <code>PIWI_COVERAGE_SERVER=lines</code> to the run&#39;s environment, which the reporter reads when your Playwright config leaves <code>coverage.server</code> unset. The backend the run calls must be the coverage build, as for any run that records server coverage. From a browser file&#39;s lens, the run records the browser&#39;s coverage by function instead (<code>PIWI_COVERAGE_BROWSER=functions</code>). When the run ends, the editor reads the file&#39;s coverage again, and the marks show what your run recorded: exactly, as long as the file is as you saved it for the run, since the reporter takes blob ids from the files on disk.</p><p>A run started anywhere else (a test&#39;s lens, the failures view, a selection) changes nothing of your config&#39;s coverage options.</p><h2 id="show-or-hide-the-marks" tabindex="-1">Show or hide the marks <a class="header-anchor" href="#show-or-hide-the-marks" aria-label="Permalink to &quot;Show or hide the marks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Editor</th><th>Command</th></tr></thead><tbody><tr><td>VS Code</td><td><strong>Piwi: Toggle the coverage marks</strong></td></tr><tr><td>JetBrains IDE</td><td><strong>Tools → Piwi → Show Coverage Marks</strong></td></tr></tbody></table><p>The command shows up once a file showed marks. The marks are shown by default; the choice is kept for the workspace in VS Code and in <code>.idea/workspace.xml</code> in a JetBrains IDE, on your machine only. The lenses and the hover stay.</p><h2 id="c-and-razor-files" tabindex="-1">C# and Razor files <a class="header-anchor" href="#c-and-razor-files" aria-label="Permalink to &quot;C# and Razor files&quot;">​</a></h2><p>Both extensions read <code>.cs</code>, <code>.cshtml</code> and <code>.razor</code> files, so an ASP.NET Core project&#39;s services, controllers and views show their marks and lenses as any application file does. The JetBrains plugin is checked on Rider; it starts once it finds a Playwright config in the solution&#39;s folder or its Git repository.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>Lines for server code only.</strong> Browser code is recorded per file or per function; recorded per function, a function that ran marks all its lines run, the branches it skipped included.</li><li><strong>The latest coverage of each test</strong>: on your branch where its tests ran with coverage, else on the default branch.</li><li><strong>API calls</strong> through Playwright&#39;s <code>request</code> fixture keep their last response&#39;s server coverage only (<a href="./server-coverage.html#limits">Server coverage</a>).</li><li>An instance without coverage shows nothing, and is asked again only on a refresh.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./code-reach.html">Code reach</a>: turning coverage on, and what it records</li><li><a href="./editors.html">Editor extensions</a>: what else the editors show</li><li><a href="./editor-runs.html">Runs from the editor</a>: running the tests a lens names</li><li><a href="./uncovered-changes.html">Uncovered changes</a>: the changed files no test reaches, on a pull request</li></ul>',32))])}const k=a(l,[["render",u]]);export{b as __pageData,k as default};
